#!/usr/bin/env python3
"""Write runtime/arky_runtime_lua.inc: the Lua sources the host runtime carries.

arky_runtime.cpp includes that file, so a host needs no build step for the Lua
part. Run this after changing runtime/async.lua or runtime/host.lua; --check
reports a stale file without writing it (the tests use it).
"""
import argparse
import sys

from build_common import ROOT

TARGET = ROOT / "runtime" / "arky_runtime_lua.inc"
SOURCES = (("async_lua", "runtime/async.lua"), ("host_lua", "runtime/host.lua"))
BYTES_PER_LINE = 24


def render():
    lines = [
        "// Generated by scripts/embed_runtime.py from " + " and ".join(path for _, path in SOURCES) + ". Do not edit.",
        "// Byte arrays, not string literals: some compilers limit the length of a literal.",
    ]
    for name, path in SOURCES:
        data = (ROOT / path).read_bytes()
        lines.append(f"const unsigned char {name}[] = {{")
        for start in range(0, len(data), BYTES_PER_LINE):
            lines.append(",".join(str(byte) for byte in data[start:start + BYTES_PER_LINE]) + ",")
        lines.append("};")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="Fail if the generated file is missing or stale")
    args = parser.parse_args()
    expected = render()
    if args.check:
        if not TARGET.is_file() or TARGET.read_text() != expected:
            sys.exit(f"embed-runtime: {TARGET.relative_to(ROOT)} is stale; run python3 scripts/embed_runtime.py")
        return
    TARGET.write_text(expected)
    print(f"Wrote {TARGET.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
